    const next = new URLSearchParams(q), current = new URLSearchParams(location.search);
    if (!next.has('m')) next.set('m', current.get('m') || 'project');
    if (current.get('topic') && next.get('m') === current.get('m')) next.set('topic', current.get('topic'));
    return next.toString();
