      onPage: (a) => history.replaceState({}, '', url(`m=${a.module}&p=${encodeURIComponent(a.id)}`)),
      // 地址先回到墙，再播卡片落回墙上
      onClose: async (a) => {
        if (wall !== w) return;
        if (new URLSearchParams(location.search).has('p')) history.pushState({}, '', url(`m=${a.module}`));
        await w.close(albums.indexOf(a));
        if (wall === w) { const q = new URLSearchParams(location.search); filterBar.hidden = ['a','p','view'].some(key => q.has(key)); }
