const partHTML = (p) => (p ? `<h3>${esc(p.label)}<small>${esc(p.role || '')}</small></h3><p>${esc(p.detail || '')}</p>` : '');

/** 部件图：点一个点，下面换成那个部件的说明 */
export function bindAnatomy(root, disc) {
  const parts = disc.anatomy?.parts || [];
  root.querySelectorAll('.pz-hot').forEach((b) => b.addEventListener('click', () => {
    root.querySelectorAll('.pz-hot').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
    const box = root.querySelector('.pz-part');
    box.innerHTML = partHTML(parts[Number(b.dataset.part)]);
    box.animate?.([{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }], { duration: 420, easing: 'cubic-bezier(0.32, 0.72, 0, 1)' });
  }));
}

const rows = (list) => `<dl class="dg-d-table"><div class="dg-rule"></div>${list.map(([k, v]) => `<div class="dg-d-block"><dt>${k}</dt><dd>${v}</dd></div><div class="dg-rule"></div>`).join('')}</dl>`;

function ioHTML(disc) {
