      const record=run[side],url=albumURLSafe(record?.evidence)?record.evidence:null;
      return [side==='before'?'未附加规则':'附加规则',`${esc(record.lines)} 行 · ${record.checks.filter(c=>c.passed).length}/${record.checks.length} 项通过${url?` · <a href="${esc(url)}" download>原始记录 ↗</a>`:''}`];
