export function pathHTML(disc, idx, { only } = {}) {
  const all = disc.path || [];
  return all.filter((s) => !only || s.id === only).map((s) => {
    const res = (s.resources || []).map((r) => {
      const href = https(r.url);
      return href ? `<a href="${esc(href)}" target="_blank" rel="noopener">${esc(r.name)} ↗</a>` : esc(r.name);
    }).join('、');
    const unlocks = (s.unlocks || []).map((id) => {
      const d = idx.discs.get(id), a = idx.albumOf(id);
      return d && a ? `<a href="${albumLink(a, d)}">${esc(d.title)}</a>` : '';
    }).filter(Boolean).join('、');
    return `<section class="dg-d-sec dg-d-block"><h3><span class="num pz-n">${String(all.indexOf(s) + 1).padStart(2, '0')}</span>${esc(s.title)}</h3><p>${esc(s.why || '')}</p>${res ? `<p class="cite">去看 ${res}</p>` : ''}${unlocks ? `<p class="cite">这一站对应的碟：${unlocks}</p>` : ''}</section>`;
  }).join('');
}

