// Shared classification for the all-project view, album selector and Opus category panel.
import { withToolAlbums } from './toolbox-catalogue.js';
import taxonomy from '../data/plaza-taxonomy.json' with { type: 'json' };
import { fuzzySearch } from './fuzzy-search.js';
import { repositoryName } from './project-catalogue.js';

export { taxonomy as PLAZA_TAXONOMY };
const aliases = new Map(taxonomy.topics.flatMap(t => [t.id, ...t.aliases].map(a => [a.toLowerCase(), t.id])));
export const topicId = value => aliases.get(String(value).toLowerCase()) || null;

export function plazaTopics(item) {
  const values = [item.category, ...(item.topics || []), ...(item.tags || []), ...(item.topicIds || [])];
  const known = new Set(values.map(topicId).filter(Boolean));
  const words = [item.title, item.idea, item.summary, item.repository].filter(Boolean).join(' ').toLowerCase();
  if (/机器人|四足|舵机|\brobot(?:ics)?\b|\bopencat\b|\bsimplefoc\b/.test(words)) known.add('robotics');
  if (/人工智能|机器学习|大模型|\bai\b|\bllm\b|machine learning/.test(words)) known.add('ai');
  if (/日常|生活|效率|笔记|待办|日历|记账|阅读|翻译|下载|播放器|浏览器|剪贴板|截图|桌面|办公|工具箱|\btodo\b|\bproductivity\b|\bdaily\b|note taking/.test(words)) known.add('daily');
  if (/嵌入式|单片机|\bmcu\b|\besp32\b|\bstm32\b|\bfirmware\b/.test(words)) known.add('embedded');
  if (/计算机|编程|开发|computer science/.test(words)) known.add('coding');
  const ids = taxonomy.topics.filter(t => known.has(t.id) && t.id !== 'other').map(t => t.id);
  return ids.length ? ids : ['other'];
}

const repoKey = value => {
  const name = repositoryName(value);
  return name ? name.toLowerCase() : null;
};

export function buildPlazaCatalogue(data, projects = []) {
  const memberships = new Map(data.discs.map(d => [d.id, data.albums.filter(a => a.discs.includes(d.id))]));
  const byRepo = new Map();
  for (const disc of data.discs) {
    const key = repoKey(disc.repository);
    if (key) byRepo.set(key, [...(byRepo.get(key) || []), disc]);
  }
  const represented = new Set();
  const decorate = (item, discs) => {
    const albums = [...new Map(discs.flatMap(d => memberships.get(d.id)).map(a => [a.id, a])).values()];
    const topics = plazaTopics({ ...item, topics: discs.flatMap(d => d.topics || []) });
    discs.forEach(d => represented.add(d.id));
    const first = albums[0], disc = discs[0];
    return { ...item, topicIds: topics, primaryTopic: topics[0],
      modules: albums.length ? [...new Set(albums.map(a => a.module))] : ['project'],
      albumIds: albums.map(a => a.id), albumTitles: albums.map(a => a.title), discIds: discs.map(d => d.id),
      albumHref: first && `albums.html?m=${first.module}&a=${encodeURIComponent(first.id)}&d=${encodeURIComponent(disc.id)}` };
  };
  const result = projects.map(p => decorate(p, byRepo.get(repoKey(p.repositoryUrl || p.links?.repo)) || []));
  for (const disc of data.discs) {
    if (represented.has(disc.id)) continue;
    result.push(decorate({ key: `disc:${disc.id}`, repository: `disc:${disc.id}`, slug: disc.id,
      title: disc.title, idea: disc.oneLiner, tags: disc.topics, repositoryUrl: disc.repository || null,
      githubStars: null, siteStars: null, tested: false, disc }, [disc]));
  }
  return result;
}

/** Keep the All page complete without replacing public identities or reviewed guide fields. */
export function discoveryCatalogue(data, projects = [], ignored = []) {
  data = withToolAlbums(data);
  const omitted = new Set(ignored.map(name => name.toLowerCase()));
  const discs = data.discs.filter(d => !omitted.has(repoKey(d.repository)));
  return buildPlazaCatalogue({ ...data, discs }, projects).map(item => {
    if (!item.disc) return item;
    const d = item.disc, source = (d.upstreams || []).find(u => /^https:\/\/github\.com\/[^/]+\/[^/#]+\/?$/.test(u.url || ''));
    return { sections:[], unknowns:[], downloads:[], evidence:[], media:{notice:'专辑作品 · 可从专辑入口打开完整体验'},
      guideState:'static', ideaLanguage:'zh', license:d.license?.name || d.license?.spdx || null,
      credit:d.upstreams?.map(u=>u.name).join(' / ') || '本站演示', ...item,
      repositoryUrl:item.repositoryUrl || source?.url || null };
  });
}

export function selectPlaza(items, { module = 'all', topic = 'all', album = '', query = '', hidden = [] } = {}) {
  const omitted = new Set(hidden);
  const base = items.filter(p => !omitted.has(p.repository));
  const matches = (p, skip) => (skip === 'module' || module === 'all' || p.modules.includes(module))
    && (skip === 'topic' || topic === 'all' || p.topicIds.includes(topicId(topic) || topic))
    && (skip === 'album' || !album || p.albumIds.includes(album));
  const searched = query.trim() ? fuzzySearch(base, query, {
    getTitle: p => p.title, getText: p => p.idea || p.summary || '',
    getKeywords: p => [...p.albumTitles, ...p.topicIds.map(id => taxonomy.topics.find(t => t.id === id)?.name), p.repository].join(' '),
    limit: Infinity,
  }) : base;
  const selected = searched.filter(p => matches(p));
  const count = (key, id, field) => searched.filter(p => matches(p, key) && p[field].includes(id)).length;
  return { items: selected, total: selected.length,
    // Group once by primary topic; cross-topic facets still find each matching work.
    groups: groupPlazaItems(selected),
    facets: {
      modules: Object.entries(taxonomy.modules).map(([id, name]) => ({ id, name, count: count('module', id, 'modules') })),
      topics: taxonomy.topics.map(t => ({ id: t.id, name: t.name, count: count('topic', t.id, 'topicIds') })),
      albums: [...new Map(base.flatMap(p => p.albumIds.map((id, i) => [id, p.albumTitles[i]]))).entries()]
        .map(([id, name]) => ({ id, name, count: count('album', id, 'albumIds') })),
    } };
}

export function groupPlazaItems(items) {
  const primary = new Map(items.map(p => [p, p.primaryTopic || plazaTopics(p)[0]]));
  return taxonomy.topics.map(t => ({ id: t.id, name: t.name, items: items.filter(p => primary.get(p) === t.id) })).filter(g => g.items.length);
}

export function plazaFilterURL(value, filters) {
  const url = new URL(value, 'https://local.invalid/');
  for (const [key, val] of Object.entries({ module: filters.module, shelf: filters.topic, album: filters.album, q: filters.query })) {
    if (val && val !== 'all') url.searchParams.set(key, val); else url.searchParams.delete(key);
  }
  // Preserve selected project and other deep-link parameters; filters never rewrite identities.
  return url.pathname.split('/').pop() + url.search + url.hash;
}

