  return taxonomy.topics.map(t => ({ id: t.id, name: t.name, items: items.filter(p => primary.get(p) === t.id) })).filter(g => g.items.length);
}

function plazaFilterURL(value, filters) {
  const url = new URL(value, 'https://local.invalid/');
  for (const [key, val] of Object.entries({ module: filters.module, shelf: filters.topic, album: filters.album, q: filters.query })) {
    if (val && val !== 'all') url.searchParams.set(key, val); else url.searchParams.delete(key);
  }
  // Preserve selected project and other deep-link parameters; filters never rewrite identities.
  return url.pathname.split('/').pop() + url.search + url.hash;
}

