// 中文按字数平分成两三截，有空格就按空格断开（多出来的并进最后一截）；书名号整段留在一起，别的标点当空格
export function splitWords(text, most = 3) {
  const t = String(text || '').replace(/》/g, '》 ').replace(/[，。、！？；：,.!?;:]/g, ' ').trim();
  if (/\s/.test(t)) { const w = t.split(/\s+/).filter(Boolean); return w.length > most ? [...w.slice(0, most - 1), w.slice(most - 1).join(' ')] : w; }
  const c = [...t], n = Math.ceil(c.length / Math.min(most, Math.max(1, Math.ceil(c.length / 3))));
  const out = [];
  for (let i = 0; i < c.length; i += n) out.push(c.slice(i, i + n).join(''));
  return out;
}
// 片名叠成两行（照原站 LADY / BIRD）：有空格在第一个空格处断，有书名号在》后断；
// 全是汉字才对半断（汉字哪里都能断）；西文单词（ODrive、SimpleFOC）不拆。字一个不少（#pd-title 的文字还是原片名）
export function stackTitle(title) {
  const t = String(title || ''), c = [...t];
  if (c.length < 4) return esc(t);
  let at = t.indexOf(' ');
  if (at < 0) { const k = t.indexOf('》'); at = k > 0 && k < t.length - 1 ? k + 1 : -1; }
  if (at < 0) {
    if (!/^[㐀-鿿豈-﫿]+$/.test(t)) return esc(t);
    const half = Math.ceil(c.length / 2);
    return `<span>${esc(c.slice(0, half).join(''))}</span><span>${esc(c.slice(half).join(''))}</span>`;
  }
  return `<span>${esc(t.slice(0, at))}</span>${t[at] === ' ' ? ' ' : ''}<span>${esc(t.slice(at).trimStart())}</span>`;
}
